# Expected values generated by test/torch/gen_audit_fixes_expected.py (torch 2.15.0).
import math
import torch
from torch.utils.data import TensorDataset, DataLoader

NAN = math.nan
INF = math.inf

def X(shape: List[int], seed: int) -> torch.Tensor:
    n = 1
    for s in shape: n *= s
    return ((torch.arange(n, dtype=torch.float64) * 0.37 + float(seed)).sin() * 2.0).reshape(shape)

def L(t: torch.Tensor) -> List[float]:
    return t.detach().double().contiguous().reshape([-1]).tolist()

def close(v: List[float], e: List[float], tol: float = 1e-10) -> bool:
    if len(v) != len(e):
        print("len", len(v), len(e)); return False
    for i in range(len(v)):
        a = v[i]; b = e[i]
        if math.isnan(b):
            if not math.isnan(a): print("at", i, a, b); return False
        elif math.isinf(b):
            if a != b: print("at", i, a, b); return False
        elif abs(a - b) > tol * max(1.0, abs(b)):
            print("at", i, a, b); return False
    return True

def batches(dl, epochs: int) -> List[List[int]]:
    r = List[List[int]]()
    for _ in range(epochs):
        for b in dl:
            r.append([int(v) for v in L(b[0])])
    return r

def test_dataloader():
    ds = TensorDataset(torch.arange(23).double())
    g = torch.Generator(); g.manual_seed(42)
    assert batches(DataLoader(ds, batch_size=5, shuffle=True, generator=g), 5) == [[0, 15, 20, 18, 19], [4, 6, 16, 21, 8], [1, 17, 14, 10, 7], [22, 3, 9, 13, 5], [11, 12, 2], [21, 14, 17, 12, 1], [4, 16, 10, 18, 0], [22, 11, 6, 13, 3], [15, 9, 7, 5, 19], [8, 2, 20], [11, 18, 6, 22, 4], [13, 5, 8, 20, 10], [0, 7, 3, 9, 21], [14, 16, 17, 19, 2], [12, 1, 15], [2, 13, 19, 22, 0], [4, 3, 9, 21, 12], [11, 1, 8, 7, 17], [16, 18, 15, 14, 6], [5, 10, 20], [11, 9, 3, 12, 10], [19, 13, 21, 15, 14], [0, 22, 7, 17, 2], [4, 20, 5, 8, 6], [16, 18, 1]]
    torch.manual_seed(7)
    assert batches(DataLoader(ds, batch_size=6, shuffle=True), 3) == [[14, 16, 9, 22, 11, 1], [15, 19, 12, 8, 2, 6], [3, 4, 5, 7, 10, 21], [13, 17, 20, 0, 18], [7, 11, 16, 3, 21, 15], [14, 1, 12, 4, 10, 2], [19, 6, 18, 0, 5, 20], [13, 22, 8, 9, 17], [10, 13, 15, 2, 19, 20], [18, 16, 1, 22, 9, 14], [5, 4, 17, 21, 0, 12], [3, 8, 6, 11, 7]]
    torch.manual_seed(3)
    assert batches(DataLoader(ds, batch_size=4, shuffle=True, drop_last=True), 3) == [[20, 16, 15, 0], [19, 21, 11, 9], [10, 22, 3, 14], [7, 5, 6, 8], [2, 12, 13, 18], [15, 13, 22, 0], [18, 14, 4, 6], [11, 16, 20, 19], [3, 7, 2, 17], [9, 21, 1, 5], [1, 2, 3, 19], [17, 11, 15, 20], [7, 0, 9, 13], [12, 8, 10, 18], [4, 14, 6, 22]]
    assert close(L(torch.rand(3)), [0.14984089136123657, 0.40146881341934204, 0.054176926612854004], 0.0)

